using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Threading;
using Qingye.Core;
namespace Qingye.UI {
    internal sealed class UsageExperience {
        readonly MainWindow owner;readonly UsageStore store;readonly DraftStore drafts;
        readonly Dictionary<string,UsageEntry> positions=new Dictionary<string,UsageEntry>(StringComparer.OrdinalIgnoreCase);
        readonly List<string> recent=new List<string>();readonly Stack<UsageEntry> closed=new Stack<UsageEntry>();
        readonly Dictionary<Document,DraftItem> restoredSources=new Dictionary<Document,DraftItem>();
        readonly Dictionary<Document,string> draftIds=new Dictionary<Document,string>();
        readonly DispatcherTimer timer=new DispatcherTimer{Interval=TimeSpan.FromSeconds(8)};
        Task pending=Task.FromResult(0);bool stopped,suppressPersist,recoveryLoading;Document readerPending;
        internal UsageOptions Options{get;private set;}
        internal Task Pending{get{return pending;}}
        internal IEnumerable<string> Recent{get{return recent.ToArray();}}
        internal UsageExperience(MainWindow owner,string root){this.owner=owner;store=new UsageStore(root);drafts=new DraftStore(root);Options=store.LoadOptions();if(Options.RecentFiles||Options.ReadingPositions)foreach(var e in store.LoadEntries()){if(!Options.ReadingPositions){e.Caret=0;e.EditorScroll=e.ReaderScroll=0;e.View=null;}positions[e.Path]=e;if(Options.RecentFiles)recent.Add(e.Path);}timer.Tick+=delegate{timer.Stop();Snapshot();};}
        void Work(Action action){pending=pending.ContinueWith(t=>action(),TaskScheduler.Default);owner.Observe(pending);}
        internal void SetOptions(UsageOptions options){Options=options;Work(()=>{store.SaveOptions(options);if(!options.RecoverDrafts){drafts.ClearOwn();drafts.ClearPending();}});if(options.RecoverDrafts)Changed();else timer.Stop();if(!options.RecentFiles)recent.Clear();owner.UpdateUsageHint();}
        internal void ClearHistory(){suppressPersist=true;recent.Clear();closed.Clear();positions.Clear();Work(store.Clear);owner.SetNotice("已清空最近文件与阅读位置");}
        internal void Opened(Document doc){if(doc.Path==null)return;suppressPersist=false;recent.RemoveAll(p=>String.Equals(p,doc.Path,StringComparison.OrdinalIgnoreCase));recent.Insert(0,doc.Path);if(recent.Count>40)recent.RemoveRange(40,recent.Count-40);UsageEntry entry;bool existed=positions.TryGetValue(doc.Path,out entry);if(!existed)positions[doc.Path]=entry=PositionOf(doc);entry.Time=entry.Updated=DateTime.UtcNow.Ticks;if(existed)Restore(doc);if(Options.RecentFiles)Persist();}
        internal UsageEntry PositionOf(Document doc){var pane=owner.primary.BoundDocument==doc?owner.primary:owner.secondary.BoundDocument==doc?owner.secondary:null;return new UsageEntry{Path=doc.Path,Caret=pane==null?0:pane.Editor.CaretOffset,EditorScroll=pane==null?0:pane.Editor.VerticalOffset,ReaderScroll=doc==owner.Current?owner.preview.ReadingOffset:0,View=doc==owner.Current?owner.Appearance.Layout:null,Time=DateTime.UtcNow.Ticks,Updated=DateTime.UtcNow.Ticks};}
        void ConsumeRestored(Document doc){DraftItem item;if(restoredSources.TryGetValue(doc,out item)){restoredSources.Remove(doc);Work(()=>drafts.Remove(item));}}
        internal void Saved(Document doc,UsageEntry before){ConsumeRestored(doc);before.Path=doc.Path;before.Time=before.Updated=DateTime.UtcNow.Ticks;positions[doc.Path]=before;Opened(doc);Changed(true);}
        internal void Capture(){CapturePane(owner.primary);if(owner.showSecondary)CapturePane(owner.secondary);}
        void CapturePane(EditorPane pane){var doc=pane.BoundDocument;if(doc==null||doc.Path==null)return;UsageEntry old;var next=PositionOf(doc);if(positions.TryGetValue(doc.Path,out old)){next.Time=old.Time;if(doc!=owner.Current){next.ReaderScroll=old.ReaderScroll;next.View=old.View;}if(old.Caret==next.Caret&&Math.Abs(old.EditorScroll-next.EditorScroll)<1&&Math.Abs(old.ReaderScroll-next.ReaderScroll)<1&&old.View==next.View)next.Updated=old.Updated;}positions[doc.Path]=next;if(positions.Count>80)positions.Remove(positions.Values.OrderBy(e=>e.Time).First().Path);}
        internal void Persist(){if(suppressPersist||!Options.RecentFiles&&!Options.ReadingPositions)return;var entries=recent.Select(p=>positions.ContainsKey(p)?positions[p].Copy():new UsageEntry{Path=p,Time=DateTime.UtcNow.Ticks}).Concat(positions.Values.Select(e=>e.Copy())).ToArray();Work(()=>store.Remember(entries));}
        internal void Restore(Document doc){if(doc==null||doc.Path==null||doc.Kind==DocumentKind.PagedText)return;UsageEntry item;if(!positions.TryGetValue(doc.Path,out item))return;if(item.View=="reader"||item.View=="single")owner.viewModes[doc]=item.View;var pane=owner.active.BoundDocument==doc?owner.active:owner.primary.BoundDocument==doc?owner.primary:owner.secondary.BoundDocument==doc?owner.secondary:null;if(pane==null)return;pane.Editor.CaretOffset=Math.Max(0,Math.Min(pane.Editor.Document.TextLength,item.Caret));pane.Editor.ScrollToVerticalOffset(Math.Max(0,item.EditorScroll));readerPending=doc;}
        internal void RestoreReader(Document doc){if(readerPending!=doc||doc==null||doc.Path==null||doc.Kind==DocumentKind.Epub)return;if(!owner.preview.CanRestoreReading(doc))return;UsageEntry item;if(positions.TryGetValue(doc.Path,out item))owner.preview.RestoreReadingOffset(item.ReaderScroll,()=>{if(readerPending==doc)readerPending=null;});}
        internal void Closed(IEnumerable<Document> docs){foreach(var doc in docs){ConsumeRestored(doc);draftIds.Remove(doc);if(doc.Path==null)continue;UsageEntry entry;closed.Push(positions.TryGetValue(doc.Path,out entry)?entry.Copy():new UsageEntry{Path=doc.Path});}if(closed.Count>20){var keep=closed.Take(20).Reverse().ToArray();closed.Clear();foreach(var e in keep)closed.Push(e);}Persist();Changed(true);}
        internal async Task ReopenAsync(){while(closed.Count>0){var entry=closed.Pop();if(!File.Exists(entry.Path))continue;positions[entry.Path]=entry;await owner.OpenPathsAsync(new[]{entry.Path},true);return;}owner.SetNotice("本次窗口没有可重新打开的文件");}
        internal void Changed(bool immediate=false){if(stopped||!Options.RecoverDrafts)return;timer.Stop();if(immediate)Snapshot();else timer.Start();}
        internal void Snapshot(){if(stopped||!Options.RecoverDrafts)return;var items=new List<DraftItem>();foreach(var doc in owner.Session.Documents.Where(d=>d.IsDirty&&!d.IsReadOnly&&d.Kind==DocumentKind.Text)){ICSharpCode.AvalonEdit.Document.TextDocument buffer;if(!owner.buffers.TryGetValue(doc,out buffer)||buffer.TextLength>1024*1024)continue;string id;if(!draftIds.TryGetValue(doc,out id))draftIds[doc]=id=Guid.NewGuid().ToString("N");items.Add(new DraftItem{Id=id,Title=doc.Title,OriginalPath=doc.Path,Text=buffer.CreateSnapshot().Text,EncodingName=doc.EncodingName,HasBom=doc.HasBom,NewLine=doc.NewLine});}Work(()=>store.WithCurrentOptions(current=>{if(current.RecoverDrafts)drafts.Write(items);else drafts.ClearOwn();}));}
        internal void ShowRecovery(){owner.Observe(ShowRecoveryAsync());}
        async Task ShowRecoveryAsync(){if(recoveryLoading)return;recoveryLoading=true;try{var items=await Task.Run(()=>drafts.Pending());if(owner.IsClosing)return;if(items.Count==0){owner.SetNotice("没有可恢复的草稿；正在其他窗口编辑的内容不会列出");return;}QuickOpen.ShowActions(owner,"恢复未保存草稿",items.Select(item=>new PaletteAction{Title=item.Title,Detail="恢复为未保存副本 · "+(item.OriginalPath??"未命名"),Run=()=>{owner.NewDocument(true);var doc=owner.Current;doc.Title="恢复 · "+item.Title;doc.EncodingName=item.EncodingName??"utf-8";doc.HasBom=item.HasBom;doc.NewLine=item.NewLine??"\r\n";owner.ActiveEditor.Document.Text=item.Text;owner.RefreshTabs();owner.UpdateStatus();restoredSources[doc]=item;Changed(true);string newId;if(Options.RecoverDrafts&&draftIds.TryGetValue(doc,out newId))Work(()=>{if(drafts.ContainsOwn(newId))drafts.Remove(item);});}}));}finally{recoveryLoading=false;}}
        internal void RefreshOptions(){var latest=store.LoadOptions();if(Options.RecoverDrafts&&!latest.RecoverDrafts){timer.Stop();Work(drafts.ClearOwn);}if(Options.RecentFiles&&!latest.RecentFiles)recent.Clear();Options=latest;owner.UpdateUsageHint();}
        internal void Startup(){owner.UpdateUsageHint();if(Options.RecoverDrafts)owner.Observe(NotifyRecoveryAsync());}
        async Task NotifyRecoveryAsync(){bool available=await Task.Run(()=>drafts.HasPending());if(available&&!owner.IsClosing)owner.SetNotice("发现未保存草稿 · Ctrl+Shift+P 搜索“恢复草稿”");}
        internal async Task ShutdownAsync(){Capture();Persist();stopped=true;timer.Stop();try{await pending;}catch{}try{await Task.Run(()=>drafts.ClearOwn());}catch(Exception e){owner.SetNotice("草稿清理未完成："+e.Message);}}
    }
    public partial class MainWindow {
        internal UsageExperience Usage;internal static string UsageRootOverride;
        internal void UpdateUsageHint(){if(WorkspaceRoot!=null)return;footer.sessionHint.Text=Usage!=null&&(Usage.Options.RecentFiles||Usage.Options.ReadingPositions||Usage.Options.RecoverDrafts)?"本地记录已开启":"本次阅读 · 不保留文件列表";}
        void InitializeUsage(){
            string usageRoot=UsageRootOverride??Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Qingye");
            if(UsageRootOverride==null&&System.Reflection.Assembly.GetEntryAssembly()!=System.Reflection.Assembly.GetExecutingAssembly())usageRoot=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"test-usage-"+System.Diagnostics.Process.GetCurrentProcess().Id);
            Usage=new UsageExperience(this,usageRoot);
        }
        internal void ShowCommands(){QuickOpen.ShowCommands(this);}
        internal void ShowPrivacySettings(){var dialog=new Window{Owner=this,Title="本地记录与恢复",Width=Math.Min(460,Math.Max(300,ActualWidth-24)),SizeToContent=SizeToContent.Height,WindowStartupLocation=WindowStartupLocation.CenterOwner,ResizeMode=ResizeMode.NoResize,ShowInTaskbar=false};Theme.Install(dialog);Theme.Apply(dialog,Appearance);var panel=new StackPanel{Margin=new Thickness(22)};panel.Children.Add(new TextBlock{Text="本地记录与恢复",FontSize=20,FontWeight=FontWeights.SemiBold,Margin=new Thickness(0,0,0,12)});panel.Children.Add(new TextBlock{Text="三个选项互相独立，默认均关闭。记录仅保存在当前 Windows 用户的本机目录。",TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,0,0,14)});var recent=new CheckBox{Content=new TextBlock{Text="记住最近文件（最多 40 项）",TextWrapping=TextWrapping.Wrap},IsChecked=Usage.Options.RecentFiles,Margin=new Thickness(0,8,0,8)};var position=new CheckBox{Content=new TextBlock{Text="记住普通文本光标与原生阅读位置",TextWrapping=TextWrapping.Wrap,ToolTip="不含大文本分段页码、网页/PDF内部位置和EPUB章节"},IsChecked=Usage.Options.ReadingPositions,Margin=new Thickness(0,8,0,8)};var drafts=new CheckBox{Content=new TextBlock{Text="启用草稿恢复（关闭时清空可清理草稿）",TextWrapping=TextWrapping.Wrap},IsChecked=Usage.Options.RecoverDrafts,Margin=new Thickness(0,8,0,8)};panel.Children.Add(recent);panel.Children.Add(position);panel.Children.Add(drafts);panel.Children.Add(new TextBlock{Text="草稿仅在修改后延迟保存：每份最多 1 Mi 字符、最多 8 份且 UTF-8 正文合计不超过 6 MiB。正常关闭或保存后清理；恢复为新副本，不覆盖原文件。",TextWrapping=TextWrapping.Wrap,FontSize=12,Margin=new Thickness(0,10,0,14)});panel.Children.Add(Theme.Button(null,"清空最近文件与阅读位置",Usage.ClearHistory));panel.Children.Add(Theme.Button(null,"查看可恢复草稿",()=>{dialog.Close();Usage.ShowRecovery();}));panel.Children.Add(Theme.Button(null,"保存设置",()=>{Usage.SetOptions(new UsageOptions{RecentFiles=recent.IsChecked==true,ReadingPositions=position.IsChecked==true,RecoverDrafts=drafts.IsChecked==true});dialog.Close();SetNotice("本地记录设置已更新");}));dialog.MaxHeight=Math.Max(300,SystemParameters.WorkArea.Height-60);dialog.Content=new ScrollViewer{Content=panel,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled};dialog.ShowDialog();}
    }
}
